formulas.expression:
IF(
	AND(
		NOT(ISBLANK({!RerunAction})),
		{!RerunAction}<> {!DoNotRerun}
	),
"Rerun Action: " + {!RerunAction} + " on " + TEXT(MONTH({!formulaRerunDate}))+"/"+TEXT(DAY({!formulaRerunDate}))+"/"+TEXT(YEAR({!formulaRerunDate})) + {!formulaLineBreak},
	IF(
		AND(
			NOT(ISBLANK({!RerunAction})),
			{!RerunAction} = {!DoNotRerun}
		),
	"Rerun Action: " + {!RerunAction} + {!formulaLineBreak},
	null
))
